from translate import ROOT
PAIRS={
'report/findings.go':[
('发现页「导出」用的渲染:把一批 findings 表行渲染成汇总 Markdown、单条 Markdown、','Finding-page export renderers: render findings rows as summary Markdown, individual Markdown,'),('或 CSV。JSON 由 server 层直接用 DTO 序列化,不在此处。','or CSV. The server serializes JSON directly from DTOs, not here.'),('sortFindingsForExport 按严重等级降序、再按时间倒序排,与汇总报告的分组一致。','sortFindingsForExport sorts by descending severity, then newest first, matching summary groups.'),('findingTitle 取漏洞可读标题:名称 → 类别 → 「未分类」。','findingTitle chooses a readable title: name → class → Unclassified.'),('FindingsMarkdown 把一批 findings 整合成一份汇总报告(摘要 + 按严重等级分组,','FindingsMarkdown combines findings into one summary report (summary and severity groups,'),('每条含类别/状态/所属任务/证据/详细报告)。','with class/status/task/evidence/detailed report for each finding).'),('摘要:各严重等级计数。','Summary: counts for each severity.'),('SingleFindingMarkdown 渲染单条漏洞为一份独立 Markdown(用于「一漏洞一文件」打包)。','SingleFindingMarkdown renders one finding as standalone Markdown for one-finding-per-file bundles.'),('FindingFilename 为「一漏洞一文件」生成安全的 .md 文件名,形如','FindingFilename generates a safe .md filename for one-finding-per-file exports, such as'),('`critical_SQL注入_#123.md`。去掉路径分隔符与控制字符,避免 zip 内非法路径。','`critical_SQL-injection_#123.md`. Strip path separators and control characters to prevent invalid ZIP paths.'),('防御性:再剥一层路径,杜绝 zip slip。','Defense in depth: strip any remaining path component to prevent ZIP slip.'),('FindingsCSV 把一批 findings 渲染成 CSV(带 UTF-8 BOM,便于 Excel 正确识别中文)。','FindingsCSV renders findings as CSV with a UTF-8 BOM so Excel recognizes Chinese correctly.'),('不含大段 report/evidence 全文,只放摘要类字段;需要全文用 Markdown/JSON 导出。','Include summary fields, not full report/evidence bodies; use Markdown/JSON for full text.')],
'notify/event.go':[
('Snapshot 是 notification_events.snapshot 这一 JSONB 列的契约。写方是 db 层的','Snapshot is the contract of the notification_events.snapshot JSONB column. The database'),('漏洞落库事务，读方是 server 层的投递引擎与过滤匹配。定义放在本包是因为它是','finding transaction writes it; the server delivery engine and filters read it. It belongs here'),('「通知领域」的载荷：db 只负责序列化，不理解字段含义。','as a notification-domain payload: db only serializes it and does not interpret its fields.'),('为什么冗余存漏洞字段而不在渲染时回查：漏洞事后会被改名、改级别、改状态，','Store finding fields redundantly rather than looking them up during rendering: findings can'),('而推送内容应当反映**事发当时**的结论——回查会得到「事后被改成 low」的','later be renamed or change severity/status. Notifications must reflect the conclusion at event time;'),('危险误导。另外 fan-out 与渲染因此不必 JOIN findings/tasks/assets 三张表。','a later downgrade to low would mislead readers. Fan-out and rendering also avoid joining findings/tasks/assets.'),('事件类型：finding_created / finding_status_changed','Event kind: finding_created / finding_status_changed'),('仅 kind=finding_status_changed 时非空。','Nonempty only for kind=finding_status_changed.'),('Item 是一条待推送的漏洞，供渠道渲染。','Item is a pending finding notification for channel rendering.'),('Assets 是解析后的资产展示名（如域名/IP）。由 server 层填充——','Assets contains resolved asset display names (e.g. domains/IPs), populated by the server;'),('本包不碰数据库，拿不到名字。','this package does not access the database and cannot resolve names.'),('DetailURL 是漏洞详情回链；为空表示未配 public_base_url，渲染时省略。','DetailURL links back to finding details; empty means public_base_url is not configured, so omit it.'),('状态变更事件专用；两项均非空时渲染成「待处理 → 已修复」。','For status-change events; when both are nonempty, render e.g. Pending → Fixed.'),('IsStatusChange 报告该条目是否为状态变更事件。','IsStatusChange reports whether this item is a status-change event.'),('Title 返回条目的展示标题：优先人工命名的 name，回退漏洞类型 vulnclass，','Title returns the display title: prefer the user-provided name, then vulnclass,'),('两者都空时用一个占位符——绝不输出空标题。','then a placeholder when both are empty; never return an empty title.'),('Message 是一次渠道发送的完整内容。','Message contains the complete content of one channel delivery.'),('单条推送时长度为 1；汇总推送（digest）时为一整批。','Length is 1 for individual delivery, or a whole batch for digest delivery.'),('空切片是非法的，调用方须保证至少一条。','An empty slice is invalid; callers must supply at least one item.'),('Batch=true 时按汇总消息渲染（换标题、带上时间窗与条数）。','Batch=true renders a digest with a different title, time window and item count.'),('WindowMinutes 是汇总周期（分钟），仅 Batch=true 时用于文案「近 N 分钟」。','WindowMinutes is the digest period in minutes, used only with Batch=true for Last N minutes.'),('刻意由配置显式传入而不是渲染时算 time.Since：渲染保持确定性，才好测。','Pass it explicitly from configuration instead of using time.Since, keeping rendering deterministic and testable.'),('HomeURL 是平台面板地址（全局 public_base_url）；空则不带面板入口。','HomeURL is the dashboard address (global public_base_url); empty omits the dashboard link.')],
'notify/channel.go':[
('Channel 是一个通知渠道的适配器。实现必须**无状态**：同一个实例会被多个渠道','Channel adapts a notification channel. Implementations must be stateless: multiple channel'),('配置并发复用，凭据一律从 cfg 参数传入。','configurations reuse one instance concurrently; all credentials come from cfg.'),('Kind 返回渠道类型标识，须与注册表的键一致。','Kind returns the channel kind identifier, which must match the registry key.'),('Validate 在保存配置时调用，校验必填字段与格式。返回的错误会直接展示给','Validate checks required fields and formats when saving configuration. Errors are shown directly to'),('配置者，所以文案要说明「缺哪个字段」而不是泛泛的「配置无效」。','the administrator, so name the missing field rather than saying only that configuration is invalid.'),('Send 投递一次消息，返回**实际送达的条目数**与错误。','Send delivers one message and returns the number of items actually delivered and an error.'),('为什么要返回条数：各平台都有消息长度上限，汇总消息装不下整批时会被截断。','Platforms limit message length; digests are truncated when the whole batch does not fit.'),('若调用方无条件把整批标记为已送达，被截掉的那些条目就消失了——消息里看不到、','If callers mark the entire batch delivered unconditionally, truncated items disappear from messages'),('投递历史里也显示成功，没有任何地方能发现漏洞从未发出。返回 kept 后，','while delivery history reports success, hiding undelivered findings. With kept,'),('调用方只标记前 kept 条，其余留待下一批。','callers mark only the first kept items delivered and leave the rest for the next batch.'),('返回错误表示投递失败，其中 *PermanentError 表示不该重试。','An error means delivery failed; *PermanentError means it must not be retried.'),('失败时 kept 无意义，调用方应忽略它。','On failure kept is meaningless and callers must ignore it.'),('DefaultRatePerMin 返回该渠道官方建议的每分钟投递上限，作为新建渠道实例','DefaultRatePerMin returns the officially recommended per-minute limit, used as the default rate'),('时的默认限流值。返回 0 表示无已知限制。','for newly created channel instances. Zero means no known limit.'),('SecretKeys 返回该渠道配置里属于凭据的键名。API 回显时这些键的值会被掩码，','SecretKeys names credential fields. The API masks their values on readback;'),('更新时收到掩码值则保留库中的原值。只有实现自己清楚哪些字段算凭据','masked incoming values retain the original stored values on update. Only the implementation knows'),('（企业微信的整个 Webhook 地址就是凭据，而钉钉的只是其中的 secret），','which fields are credentials (the whole WeCom Webhook URL, versus DingTalk signing secret),'),('所以这个知识必须由渠道提供，不能由上层猜测。','so channels must declare this knowledge rather than requiring higher layers to guess.'),('DestinationKeys 返回该渠道配置里决定「消息发往哪里」的键名。','DestinationKeys names configuration fields determining where messages are sent.'),('与 SecretKeys 一样是安全相关的东西：目标地址与凭据是两套独立字段，','Like SecretKeys this is security-sensitive: destinations and credentials are separate fields.'),('若允许「只改地址、凭据原样保留」，任何能改渠道配置的人都能把库里的真凭据','Allowing destination changes while retaining credentials would let anyone who can edit channel settings'),('发到自己控制的服务器，渠道配置的掩码就完全失去意义。','send stored credentials to a server they control, defeating configuration masking.'),('详见 PrepareConfigUpdate。','See PrepareConfigUpdate.'),('registry 是渠道注册表。刻意用显式字面量而不是 init() 自注册：这样「有哪些渠道」','registry is explicit rather than self-registering via init(), so all supported channels are visible'),('在一个地方就能看全，且新增渠道会在编译期暴露遗漏，而不是靠运行时副作用。','in one place and adding channels exposes omissions at compile time rather than relying on runtime side effects.'),('Get 按类型取渠道实现。','Get returns the implementation for a channel kind.'),('ValidKind 报告 kind 是否为受支持的渠道类型。','ValidKind reports whether a channel kind is supported.'),('Kinds 返回全部受支持的渠道类型，按字典序排列（供 UI 下拉稳定展示）。','Kinds returns all supported channel kinds in lexical order for stable UI dropdowns.'),('PermanentError 标记一个不该重试的投递失败：凭据错误、目标拒绝、请求体非法等。','PermanentError marks a nonretryable delivery failure: bad credentials, destination rejection, invalid body, etc.'),('重试只对瞬时故障（网络抖动、限流、对端 5xx）有意义；对永久失败反复退避重试','Retries only help transient failures (network instability, rate limits, remote 5xx); repeated backoff on'),('既不会成功，又会把真正的错误刷没在重试日志里。','permanent failures cannot succeed and buries the actual error in retry logs.'),('Permanent 把 err 标记为永久失败。err 为 nil 时返回 nil，','Permanent marks err as a permanent failure. It returns nil for nil err,'),('方便写成 `return Permanent(someCheck())`。','allowing `return Permanent(someCheck())`.'),('IsPermanent 报告 err 链上是否带有永久失败标记。','IsPermanent reports whether the error chain contains a permanent-failure marker.'),('---- 配置读取helper ----','---- Configuration reading helpers ----'),('渠道配置来自数据库的 JSONB 列，经 encoding/json 反序列化后是 map[string]any，','Channel configuration comes from a JSONB column, decoded by encoding/json as map[string]any;'),('数值一律是 float64、数组是 []any。下面这些 helper 统一这层转换，并容忍用户','numbers are float64 and arrays are []any. These helpers centralize conversion and tolerate'),('在 UI 里留空导致的类型偏差（如把端口填成字符串）。','type differences caused by empty UI inputs (e.g. a string-valued port).'),('cfgString 取字符串配置项，前后空白一律裁掉——从网页表单复制粘贴很容易带上。','cfgString reads a string and trims whitespace often introduced by copying from web forms.'),('cfgInt 取整数配置项，兼容 float64（JSON 默认）与字符串两种来源。','cfgInt reads an integer from float64 (the JSON default) or a string.'),('cfgBool 取布尔配置项，兼容字符串 "true"/"1"。','cfgBool reads a boolean, accepting strings "true"/"1".'),('cfgStrings 取字符串数组配置项，自动裁空白并丢弃空串。','cfgStrings reads a string array, trims whitespace and drops empty values.'),('也接受单个字符串，方便只有一个值时的表单提交。','Also accept a single string for forms submitting one value.'),('cfgMap 取字符串映射配置项（如自定义 HTTP 头），键值都裁空白，丢弃空键。','cfgMap reads a string map (e.g. custom HTTP headers), trims keys/values and drops empty keys.')]
}
if __name__=='__main__':
 for rel,pairs in PAIRS.items():
  f=ROOT/'source'/rel;s=f.read_text()
  for a,b in pairs:
   assert a in s,(rel,a);s=s.replace(a,b)
  f.write_text(s)
